function sqlSegments(text,commas=false){let depth=0,quote='',line=false,block=false,out=[],start=0;for(let i=0;i<text.length;i++){const c=text[i],n=text[i+1];if(line){if(c==='\n')line=false;continue}if(block){if(c==='*'&&n==='/'){block=false;i++}continue}if(quote){if(c===quote){if(n===quote)i++;else quote=''}else if(quote===']'&&c===']')quote='';continue}if(c==='-'&&n==='-'){line=true;i++;continue}if(c==='/'&&n==='*'){block=true;i++;continue}if(c==="'"||c==='"'||c==='`'||c==='['){quote=c==='['?']':c;continue}if(c==='(')depth++;if(c===')')depth--;if(depth===0){if(commas&&c===','){out.push(text.slice(start,i));start=i+1}else if(!commas&&/[a-zA-Z_]/.test(c)&&(i===0||!/[\w]/.test(text[i-1]))){const word=text.slice(i).match(/^[a-zA-Z_][\w]*/)[0];out.push({word:word.toUpperCase(),index:i,end:i+word.length});i+=word.length-1}}}if(commas)out.push(text.slice(start));return out}
function detectSqlFields(query){const tokens=sqlSegments(query);const select=tokens.find(t=>t.word==='SELECT');if(!select)throw Error('Enter a SELECT query.');const from=tokens.find(t=>t.index>select.index&&t.word==='FROM');const projection=query.slice(select.end,from?.index||query.length).replace(/^\s*DISTINCT\s+/i,'').replace(/;\s*$/,'');const parts=sqlSegments(projection,true);if(!parts.length)throw Error('No output fields found.');const seen=new Set();return parts.map(raw=>{const expression=raw.replace(/--[^\n]*/g,'').replace(/\/\*[\s\S]*?\*\//g,'').trim();if(expression==='*'||/^\w+\.\*$/.test(expression))throw Error('List the output columns explicitly. SELECT * needs a live database connection.');let match=expression.match(/\bAS\s+(?:"([^"]+)"|`([^`]+)`|\[([^\]]+)\]|([a-zA-Z_]\w*))\s*$/i);let column=match&&(match[1]||match[2]||match[3]||match[4]);if(!column){match=expression.match(/^(?:[a-zA-Z_]\w*\.)?["`\[]?([a-zA-Z_]\w*)["`\]]?$/);if(match)column=match[1];else{match=expression.match(/\s+([a-zA-Z_]\w*)$/);if(match&&!['END','NULL','TRUE','FALSE'].includes(match[1].toUpperCase()))column=match[1]}}if(!column)throw Error('Add AS <column_name> to each calculated output.');if(!/^[a-zA-Z_]\w*$/.test(column))throw Error('Use output names containing letters, numbers and underscores.');if(seen.has(column.toLowerCase()))throw Error('Use unique output names: '+column);seen.add(column.toLowerCase());const dataType=/\b(?:DATE|TIMESTAMP)\s*\(|\bAS\s+(?:DATE|TIMESTAMP)\b/i.test(expression)?'Date':/\bCOUNT\s*\(/i.test(expression)?'Integer':/\b(?:SUM|AVG)\s*\(|\b(?:FLOAT|DECIMAL|NUMERIC|DOUBLE)\b|\s\/\s/i.test(expression)?'Float':/\b(?:INTEGER|BIGINT|INT)\b/i.test(expression)?'Integer':'Character';return {column,name:column.replaceAll('_',' '),dataType,expression}})}
function queryFieldError(id,message){const el=document.getElementById(id);if(el)el.innerHTML=`<div class="notice error">${esc(message)}</div>`}
// Tech / Product: a new mapping starts with an entity and its own query.
let newMappingSerial=10;
const detectBaseList=mappingList;
mappingList=function(){return detectBaseList().replace('<span class="badge">','<button class="button primary" id="addEntity">+ Add entity</button><span class="badge">')};
const detectBaseEditor=mappingEditor;
mappingEditor=function(){let html=detectBaseEditor();if(mappingDraft.isNew){const m=mappingDraft;html=`<div class="titlebar"><h1>Add entity</h1><button class="button" id="cancelNewEntity">Cancel</button></div><section class="panel"><div class="panel-head"><h2>Entity mapping</h2></div><div class="panel-body"><div class="grid"><div class="group"><label class="label" for="newLob">Business Line</label><input type="text" id="newLob" list="businessLines" value="${esc(m.lob)}" placeholder="e.g. Last Mile"><datalist id="businessLines">${[...new Set(entityMappings.map(x=>x.lob))].map(l=>`<option value="${esc(l)}">`).join('')}</datalist></div><div class="group"><label class="label" for="newEntity">Entity</label><input type="text" id="newEntity" value="${esc(m.entity)}" placeholder="e.g. Rider"></div><div class="group"><label class="label" for="newDescription">Description</label><input type="text" id="newDescription" value="${esc(m.description)}"></div></div></div></section>${entityQuerySection()}<section class="panel"><div class="panel-head"><h2>Detected entity fields</h2></div><div class="panel-body">${m.parameters.length?detectedEntityTable(): '<span class="quiet">Add a query and select Detect fields.</span>'}</div></section><div class="savebar"><button class="button primary" id="mappingSave">Save whitelist</button></div>`}else{html=html.replace('<h2>Entity fields</h2>','<h2>Entity fields</h2>');const start=html.indexOf('<div class="tablewrap"><table><thead><tr><th>FIELD');if(start>=0){const end=html.indexOf('</table></div>',start);html=html.slice(0,start)+detectedEntityTable()+html.slice(end+14)}}return html.replace('<button class="button" id="checkEntityQuery">','<button class="button primary" id="detectEntityFields">Detect fields</button><button class="button" id="checkEntityQuery">')};
function detectedEntityTable(){return `<div class="tablewrap"><table><thead><tr><th>ENTITY ID ${info('Select the unique entity identifier returned by this query.')}</th><th>QUERY COLUMN</th><th>FIELD NAME</th><th>DATA TYPE</th><th>INCLUDE</th><th>ENTITY FILTER</th></tr></thead><tbody>${mappingDraft.parameters.map((p,i)=>`<tr><td><input type="radio" name="entityIdentifier" data-entity-identity="${i}" ${p.identity?'checked':''} aria-label="Use ${esc(p.column)} as entity ID"></td><td><code>${esc(p.column)}</code></td><td><input type="text" data-entity-label="${i}" value="${esc(p.name)}" aria-label="${esc(p.column)} field name"></td><td><select data-entity-type="${i}" aria-label="${esc(p.column)} data type">${selectedOptions(['Character','Integer','Float','Date'],p.type)}</select></td><td><input type="checkbox" data-parameter-include="${i}" ${p.included?'checked':''} ${p.identity?'disabled':''} aria-label="Include ${esc(p.name)}"></td><td><input type="checkbox" data-parameter-filter="${i}" ${p.filter?'checked':''} ${!p.included?'disabled':''} aria-label="Whitelist ${esc(p.name)} as a filter"></td></tr>`).join('')}</tbody></table></div>`}
function detectEntityFields(){try{const columns=detectSqlFields(mappingDraft.query);const old=mappingDraft.parameters;mappingDraft.parameters=columns.map(f=>{const prior=old.find(p=>p.column===f.column);return prior?structuredClone(prior):{column:f.column,name:f.name,type:f.dataType,included:true,filter:true,identity:false}});mappingDraft.detectedQuery=mappingDraft.query;render();return true}catch(e){queryFieldError('entityQueryResult',e.message);return false}}
const detectBaseBindings=bindMappings;
bindMappings=function(){detectBaseBindings();document.getElementById('addEntity')?.addEventListener('click',()=>{mappingDraft={id:'mapping-new-'+newMappingSerial++,lob:'',entity:'',source:'',description:'',enabled:true,isNew:true,query:'',parameters:[]};render()});document.getElementById('cancelNewEntity')?.addEventListener('click',()=>{mappingDraft=null;render()});for(const [id,key] of [['newLob','lob'],['newEntity','entity'],['newDescription','description']])document.getElementById(id)?.addEventListener('input',e=>mappingDraft[key]=e.target.value);document.getElementById('detectEntityFields')?.addEventListener('click',detectEntityFields);document.querySelectorAll('[data-entity-label]').forEach(el=>el.oninput=()=>mappingDraft.parameters[Number(el.dataset.entityLabel)].name=el.value);document.querySelectorAll('[data-entity-identity]').forEach(el=>el.onchange=()=>{mappingDraft.parameters.forEach((p,i)=>{p.identity=i===Number(el.dataset.entityIdentity);if(p.identity)p.included=true});render()})};
validateEntityQuery=function(m){if(!m.query?.trim())return 'Enter a SQL query for this entity.';if(!m.parameters.length)return 'Detect fields from the query first.';const active=m.parameters.filter(p=>p.included);if(active.filter(p=>p.identity).length!==1)return 'Select one included field as the entity ID.';if(active.some(p=>!p.name.trim()))return 'Enter a name for every included field.';if(new Set(active.map(p=>p.name.trim().toLowerCase())).size!==active.length)return 'Use a different name for each included field.';try{const cols=detectSqlFields(m.query).map(f=>f.column);const missing=active.filter(p=>!cols.includes(p.column));if(missing.length)return 'Query output is missing: '+missing.map(p=>p.column).join(', ');return ''}catch(e){return e.message}};
const detectPreviousSave=saveMapping;
saveMapping=function(){if(!mappingDraft.lob.trim()||!mappingDraft.entity.trim()){queryFieldError('entityQueryResult','Enter a Business Line and Entity.');return false}if(entityMappings.some(m=>m.id!==mappingDraft.id&&m.lob.toLowerCase()===mappingDraft.lob.trim().toLowerCase()&&m.entity.toLowerCase()===mappingDraft.entity.trim().toLowerCase())){queryFieldError('entityQueryResult','This Business Line and Entity mapping already exists.');return false}if(!mappingDraft.isNew)return detectPreviousSave();if(!checkEntityQuery())return false;const item=structuredClone(mappingDraft);delete item.isNew;item.lob=item.lob.trim();item.entity=item.entity.trim();entityMappings.push(item);mappingDraft=null;render();toast('Entity and detected fields added to the whitelist.');return true};
// Field registry: one query can register a primary metric and additional metrics.
let registryQueryDraft=null;
const metricSampleQuery=`SELECT\n  DATE(dispatched_at) AS date,\n  rider_id AS entity_id,\n  shipment_type AS field_filter1,\n  COUNT(DISTINCT CASE WHEN status = 'Closed'\n    THEN shipment_id END) AS closed_shipments,\n  COUNT(DISTINCT shipment_id) AS dispatched_shipments\nFROM shipment_activity\nGROUP BY 1, 2, 3`;
openField=function(index){editing=index;const existing=index>=0?fields[index]:null;registryQueryDraft={existingId:existing?.id||null,groupId:existing?.queryGroup||existing?.id||'query-'+Date.now(),name:existing?.name||'',sql:existing?.sql||metricSampleQuery,columns:[],primary:existing?.valueColumn||'',dateColumn:existing?.dateColumn||'',entityIdColumn:existing?.entityIdColumn||'',sample:existing?.sample||[42,58,36]};if(existing)populateRegistryColumns();renderRegistryQuery();document.getElementById('fieldDialog').showModal()};
function populateRegistryColumns(){const d=registryQueryDraft,found=detectSqlFields(d.sql);const existing=fields.find(f=>f.id===d.existingId);d.columns=found.map(f=>{const old=d.columns.find(c=>c.column===f.column);if(old)return old;const mapped=existing?.filterColumns?.find(c=>c.column===f.column);const metric=fields.find(v=>(v.queryGroup||v.id)===d.groupId&&v.valueColumn===f.column);return {...f,name:metric?.name||mapped?.label||f.name,dataType:metric?(metric.kind==='Percentage'?'Float':metric.kind):mapped?.dataType||f.dataType,kind:metric?.kind,role:[d.dateColumn,d.entityIdColumn].includes(f.column)?'Required':mapped?'Filter':metric&&metric.id!==d.existingId?'Other field':'Ignore',filterKey:mapped?.key}});if(!d.columns.some(c=>c.column===d.primary))d.primary=d.columns.find(c=>['Integer','Float'].includes(c.dataType)&&c.role!=='Required')?.column||'';const primary=d.columns.find(c=>c.column===d.primary);if(primary){primary.role='Primary';if(primary.dataType==='Character'&&existing)primary.dataType='Float'}d.detectedSql=d.sql;return d.columns}
function renderRegistryQuery(){const d=registryQueryDraft,dialog=document.getElementById('fieldDialog');dialog.classList.remove('details-dialog');dialog.innerHTML=`<div class="panel-head"><h2 id="dialogTitle">${d.existingId?'Edit field query':'Create fields from query'}</h2><button class="close" id="closeQueryRegistry" aria-label="Close">×</button></div><div class="dialogbody"><div class="group"><label class="label" for="registrySql">SQL query ${info('Use explicit output columns or aliases. Select which output columns contain the date and entity ID. Detection reads column names and suggests data types; it does not execute SQL.')}</label><textarea id="registrySql" spellcheck="false">${esc(d.sql)}</textarea></div><button class="button primary" id="detectRegistryFields">Detect fields</button><div id="registryDetectionResult" role="status"></div>${d.columns.length?`${registryColumnMappings()}<div class="grid" style="margin-top:24px"><div class="group"><label class="label" for="registryPrimary">Primary field ${info('The main numeric output to register from this query. Other numeric outputs can be registered as additional fields.')}</label><select id="registryPrimary"><option value="">Select a numeric field</option>${d.columns.filter(c=>c.role!=='Required'&&['Integer','Float'].includes(c.dataType)).map(c=>`<option value="${c.column}" ${c.column===d.primary?'selected':''}>${esc(c.name)} (${esc(c.column)})</option>`).join('')}</select></div><div class="group"><label class="label" for="registryName">Primary field name</label><input type="text" id="registryName" value="${esc(d.name||'')}" placeholder="e.g. Closed Shipments"></div></div><div class="tablewrap"><table><thead><tr><th>QUERY COLUMN</th><th>FIELD NAME</th><th>DATA TYPE</th><th>USE AS ${info('Other field registers another numeric metric. Filter exposes a query attribute for conditions. Ignore leaves a column unused.')}</th></tr></thead><tbody>${d.columns.map((c,i)=>`<tr><td><code>${esc(c.column)}</code></td><td><input type="text" data-output-name="${i}" value="${esc(c.name)}" aria-label="${c.column} name" ${c.role==='Required'?'disabled':''}></td><td><select data-output-type="${i}" aria-label="${c.column} type" ${c.role==='Required'?'disabled':''}>${selectedOptions(['Character','Integer','Float','Date','Percentage'],c.kind==='Percentage'?'Percentage':c.dataType)}</select></td><td>${c.role==='Required'?'<span class="tag">Required</span>':c.column===d.primary?'<span class="tag">Primary</span>':`<select data-output-role="${i}" aria-label="${c.column} usage">${selectedOptions(['Character','Date'].includes(c.dataType)?['Ignore','Filter']:['Ignore','Other field','Filter'],c.role)}</select>`}</td></tr>`).join('')}</tbody></table></div><p class="quiet">Field names and types can be adjusted. Filter values are entered during incentive configuration.</p>`:''}<div class="savebar"><button class="button" id="cancelRegistryQuery">Cancel</button><button class="button primary" id="saveRegistryQuery" ${!d.columns.length?'disabled':''}>Save fields</button></div></div>`;document.getElementById('closeQueryRegistry').onclick=document.getElementById('cancelRegistryQuery').onclick=()=>dialog.close();document.getElementById('registrySql').oninput=e=>{d.sql=e.target.value};document.getElementById('detectRegistryFields').onclick=()=>{try{populateRegistryColumns();if(!d.name)d.name=d.columns.find(c=>c.column===d.primary)?.name||'';renderRegistryQuery()}catch(e){queryFieldError('registryDetectionResult',e.message)}};document.getElementById('registryPrimary')?.addEventListener('change',e=>{d.columns.forEach(c=>{if(c.role==='Primary')c.role='Ignore'});d.primary=e.target.value;const c=d.columns.find(c=>c.column===d.primary);if(c){c.role='Primary';d.name=c.name}renderRegistryQuery()});document.getElementById('registryName')?.addEventListener('input',e=>d.name=e.target.value);document.querySelectorAll('[data-output-name]').forEach(el=>el.oninput=()=>{d.columns[Number(el.dataset.outputName)].name=el.value});document.querySelectorAll('[data-output-type]').forEach(el=>el.onchange=()=>{const c=d.columns[Number(el.dataset.outputType)];c.kind=el.value;c.dataType=el.value==='Percentage'?'Float':el.value;if(['Character','Date'].includes(c.dataType)){if(c.column===d.primary)d.primary='';if(c.role==='Other field'||c.role==='Primary')c.role='Ignore'}renderRegistryQuery()});document.querySelectorAll('[data-output-role]').forEach(el=>el.onchange=()=>{d.columns[Number(el.dataset.outputRole)].role=el.value});bindRegistryColumnMappings();document.getElementById('saveRegistryQuery').onclick=saveRegistryQuery}
function saveRegistryQuery(){const d=registryQueryDraft;try{if(d.sql!==d.detectedSql)throw Error('The query has changed. Detect fields again before saving.');if(!d.dateColumn||!d.entityIdColumn)throw Error('Select the Date and Entity ID columns.');if(d.dateColumn===d.entityIdColumn)throw Error('Date and Entity ID must use different columns.');if(!d.columns.some(c=>c.column===d.dateColumn&&c.dataType==='Date'))throw Error('Select a Date column with Date data type.');if(!d.columns.some(c=>c.column===d.entityIdColumn))throw Error('The Entity ID column is missing from this query.');const primary=d.columns.find(c=>c.column===d.primary);if(!primary||!['Integer','Float'].includes(primary.dataType)||[d.dateColumn,d.entityIdColumn].includes(primary.column))throw Error('Select a numeric primary field.');if(!d.name.trim())throw Error('Enter the primary field name.');const metrics=[primary,...d.columns.filter(c=>c.role==='Other field'&&c.column!==d.primary)];const metricNames=metrics.map(c=>c===primary?d.name.trim():c.name.trim());if(metricNames.some(n=>!n)||new Set(metricNames.map(n=>n.toLowerCase())).size!==metricNames.length)throw Error('Use a unique name for each selected field.');if(d.columns.some(c=>c.role==='Filter'&&!c.name.trim()))throw Error('Enter a name for each filter.');const metricIds=metrics.map(c=>c===primary?(d.existingId||d.groupId+':'+c.column):(fields.find(f=>f.queryGroup===d.groupId&&f.valueColumn===c.column)?.id||d.groupId+':'+c.column));if(fields.some(f=>!metricIds.includes(f.id)&&metricNames.some(n=>n.toLowerCase()===f.name.toLowerCase())))throw Error('A selected field name already exists.');const filterColumns=d.columns.filter(c=>c.role==='Filter').map(c=>({key:c.filterKey||d.groupId+':'+c.column,column:c.column,label:c.name.trim(),dataType:c.dataType,values:[]}));filterColumns.forEach(c=>{keys[c.key]??=[];keyNames[c.key]=c.label;keyHelp[c.key]='Values from '+c.column+'.'});metrics.forEach((c,i)=>{const old=fields.find(f=>f.id===metricIds[i]);const item={id:metricIds[i],queryGroup:d.groupId,name:metricNames[i],kind:c.kind||c.dataType,unit:old?.unit||'Numeric value',keys:filterColumns.map(f=>f.key),filterColumns:structuredClone(filterColumns),valueColumn:c.column,dateColumn:d.dateColumn,entityIdColumn:d.entityIdColumn,sql:d.sql,formula:c.expression,sample:old?.sample||d.sample};if(old)fields[fields.indexOf(old)]=item;else fields.push(item)});document.getElementById('fieldDialog').close();render();toast(metrics.length+' field'+(metrics.length===1?'':'s')+' saved to the registry.');return true}catch(e){queryFieldError('registryDetectionResult',e.message);return false}}
render();
